customCSS:
.t, .history { color: #6e6a86; }
.join { color: #a3be8c; }
.part, .quit { color: #6e6a86; }
.kick, .error { color: #eb6f92; }
.notice { color: #f6c177; }
.action { color: #c4a7e7; }
.mode, .nick, .topic, .server { color: #9ccfd8; }
.highlight { color: #e0def4; background-color: #433c59; border-left: 3px solid #c4a7e7; padding-left: 8px; }
.reply { color: #6e6a86; border-left: 2px solid #569fba; padding-left: 6px; }
.oper { color: #232136; background-color: #f6c177; }
.reactions { color: #569fba; background-color: #393552; }
.card { background-color: #393552; border-color: #6e6a86; }
.card-title { color: #569fba; }
.card-desc { color: #6e6a86; }
.daychange { color: #6e6a86; border-color: #393552; }
